protected void pushEntitiesAway() {
		boolean collision = false;

		double maxReverseX = -1;
		double maxReverseZ = -1;

		AxisAlignedBB collisionAABB = this.getCollisionBoundingBox();
		if(collisionAABB != null) {
			List<Entity> entities = this.world.getEntitiesWithinAABBExcludingEntity(this, collisionAABB);

			for(Entity entity : entities) {
				if(entity.canBeCollidedWith()) {
					if(!entity.canBePushed() && entity instanceof EntityMovingWall == false) {
						collision = true;
					} else {
						AxisAlignedBB entityAABB = entity.getEntityBoundingBox();
						boolean squished = false;
						double dx = Math.max(collisionAABB.minX - entityAABB.maxX, entityAABB.minX - collisionAABB.maxX);
						double dz = Math.max(collisionAABB.minZ - entityAABB.maxZ, entityAABB.minZ - collisionAABB.maxZ);

						if(Math.abs(dz) < Math.abs(dx)) {
							entity.move(MoverType.PISTON, 0, 0, (dz - 0.005D) * Math.signum(this.posZ - entity.posZ));
							entityAABB = entity.getEntityBoundingBox();
							dz = Math.max(collisionAABB.minZ - entityAABB.maxZ, entityAABB.minZ - collisionAABB.maxZ);

							if(-dz > 0.025D) {
								squished = true;
								maxReverseZ = Math.max(-dz, maxReverseZ);
							}
						} else {
							entity.move(MoverType.PISTON, (dx - 0.005D) * Math.signum(this.posX - entity.posX), 0, 0);
							entityAABB = entity.getEntityBoundingBox();
							dx = Math.max(collisionAABB.minX - entityAABB.maxX, entityAABB.minX - collisionAABB.maxX);

							if(-dx > 0.025D) {
								squished = true;
								maxReverseX = Math.max(-dx, maxReverseX);
							}
						}

						//Move slightly towards ground to update onGround state etc.
						entity.move(MoverType.PISTON, 0, -0.01D, 0);

						if(squished) {
							collision = true;

							if(!this.world.isRemote) {
								entity.attackEntityFrom(DamageSource.IN_WALL, 10F);
								setHoldStill(true);
								holdCount = 20;
								getEntityWorld().playSound(null, getPosition(), SoundRegistry.WALL_SLAM, SoundCategory.HOSTILE, 0.5F, 0.75F);
							}
						}
					}
				}
			}
		}

		if(collision) {
			if(maxReverseZ > 0) {
				this.posZ -= (maxReverseZ + 0.05D) * Math.signum(this.motionZ);
			}
			if(maxReverseX > 0) {
				this.posX -= (maxReverseX + 0.05D) * Math.signum(this.motionX);
			}

			shaking = true;
			shake_timer = 0;

			if(!this.world.isRemote) {
				motionX *= -1D;
				motionZ *= -1D;
				velocityChanged = true;
			}
		}
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		if (!getEntityWorld().isRemote) {
			if(ticksExisted == 1 && isNewSpawn())
				checkSpawnArea();

			if(ticksExisted == 2) //needs to have moved 1 tick for direction to work
				doJankSafetyCheck();

			if(isHoldingStill()) {
				holdCount--;
				if (holdCount <= 0) {
					setHoldStill(false);
					holdCount = 20;
				}
			}
		}

		calculateAllCollisions(posX, posY + 0.5D, posZ);
		calculateAllCollisions(posX, posY - 0.5D, posZ);
		calculateAllCollisions(posX, posY + 1.5D, posZ);

		if (getHorizontalFacing() == EnumFacing.NORTH || getHorizontalFacing() == EnumFacing.SOUTH) {
			calculateAllCollisions(posX - 1D, posY + 0.5D, posZ);
			calculateAllCollisions(posX - 1D, posY - 0.5D, posZ);
			calculateAllCollisions(posX - 1D, posY + 1.5D, posZ);
			calculateAllCollisions(posX + 1D, posY + 0.5D, posZ);
			calculateAllCollisions(posX + 1D, posY - 0.5D, posZ);
			calculateAllCollisions(posX + 1D, posY + 1.5D, posZ);
		} else {
			calculateAllCollisions(posX, posY + 0.5D, posZ - 1D);
			calculateAllCollisions(posX, posY - 0.5D, posZ - 1D);
			calculateAllCollisions(posX, posY + 1.5D, posZ - 1D);
			calculateAllCollisions(posX, posY + 0.5D, posZ + 1D);
			calculateAllCollisions(posX, posY - 0.5D, posZ + 1D);
			calculateAllCollisions(posX, posY + 1.5D, posZ + 1D);
		}
		if (!this.world.isRemote && this.impacts > 0) {
			if (this.impacts-- > 2) {
				this.setDead();
				return;
			}
		}

		EnumFacing heading = EnumFacing.getFacingFromVector((float)motionX, 0, (float)motionZ);

		if(this.isBlockAligned) {
			if(heading.getAxis() != Axis.Z) {
				this.posZ = MathHelper.floor(this.posZ) + 0.5D;
			}
			if(heading.getAxis() != Axis.X) {
				this.posX = MathHelper.floor(this.posX) + 0.5D;
			}
		}

		if(!isHoldingStill()) {
			motionY = 0;
			motionX = heading.getXOffset() * speed;
			motionZ = heading.getZOffset() * speed;

			posX += motionX;
			posY += motionY;
			posZ += motionZ;

			this.pushEntitiesAway();
		}

		rotationPitch = 0;
		rotationYaw = (float) (MathHelper.atan2(-motionX, motionZ) * (180D / Math.PI));
		setPosition(posX, posY, posZ);
		setEntityBoundingBox(getCollisionBoundingBox());

		if (isShaking())
			shake(10);

		if (getEntityWorld().isRemote) {
			if (isHoldingStill())
				if (!playSlideSound)
					playSlideSound = true;

			if (!isHoldingStill())
				if (playSlideSound) {
					playSlidingSound(getEntityWorld(), getPosition());
					playSlideSound = false;
				}
		}

		//Remove wall if it is a dungeon wall and the dungeon is defeated
		if(!this.world.isRemote && this.isDungeonWall) {
			List<LocationSludgeWormDungeon> dungeons = BetweenlandsWorldStorage.forWorld(this.world).getLocalStorageHandler().getLocalStorages(LocationSludgeWormDungeon.class, this.getEntityBoundingBox(), l -> true);

			if(dungeons.isEmpty()) {
				this.setDead();
			} else {
				for(LocationSludgeWormDungeon dungeon : dungeons) {
					if(dungeon.isDefeated()) {
						this.setDead();
						break;
					}
				}
			}
		}
	}

public void calculateAllCollisions(double posX, double posY, double posZ) {
		Vec3d vec3d = new Vec3d(posX, posY, posZ);
		Vec3d vec3d1 = new Vec3d(posX + motionX * 12D, posY + motionY, posZ + motionZ * 12D); //adjust multiplier higher for slower speeds
		RayTraceResult raytraceresult = world.rayTraceBlocks(vec3d, vec3d1);
		vec3d = new Vec3d(posX, posY, posZ);
		vec3d1 = new Vec3d(posX + motionX, posY + motionY, posZ + motionZ);

		if (raytraceresult != null)
			vec3d1 = new Vec3d(raytraceresult.hitVec.x, raytraceresult.hitVec.y, raytraceresult.hitVec.z);

		Entity entity = null;
		List<Entity> list = world.getEntitiesWithinAABBExcludingEntity(this, getCollisionBoundingBox().expand(motionX, motionY, motionZ).grow(1.0D));
		double d0 = 0.0D;
		boolean ignore = false;

		for (int entityCount = 0; entityCount < list.size(); ++entityCount) {
			Entity entity1 = list.get(entityCount);

			if (entity1.canBeCollidedWith()) {
				if (entity1 == ignoreEntity)
					ignore = true;
				else if (ticksExisted < 2 && ignoreEntity == null) {
					ignoreEntity = entity1;
					ignore = true;
				} else {
					ignore = false;
					AxisAlignedBB axisalignedbb = entity1.getEntityBoundingBox().grow(0.30000001192092896D);
					RayTraceResult raytraceresult1 = axisalignedbb.calculateIntercept(vec3d, vec3d1);

					if (raytraceresult1 != null) {
						double d1 = vec3d.squareDistanceTo(raytraceresult1.hitVec);

						if (d1 < d0 || d0 == 0.0D) {
							entity = entity1;
							d0 = d1;
						}
					}
				}
			}
		}

		if (ignoreEntity != null) {
			if (ignore)
				ignoreTime = 2;
			else if (ignoreTime-- <= 0)
				ignoreEntity = null;
		}

		if (entity != null)
			raytraceresult = new RayTraceResult(entity);

		if (raytraceresult != null)
			onImpact(raytraceresult);
	}

protected void onImpact(RayTraceResult result) {
		if (result.typeOfHit == RayTraceResult.Type.BLOCK) {
			IBlockState state = getEntityWorld().getBlockState(result.getBlockPos());
			if (isUnbreakableBlock(state)) { // not sure of all the different states so default will do
				if (result.sideHit.getIndex() == 2 || result.sideHit.getIndex() == 3) {
					shaking = true;
					shake_timer = 0;
					motionZ *= -1D;
					velocityChanged = true;
					if(!getEntityWorld().isRemote) {
						setHoldStill(true);
						holdCount = 20;
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.WALL_SLAM, SoundCategory.HOSTILE, 0.5F, 0.75F);
					}
				} else if (result.sideHit.getIndex() == 4 || result.sideHit.getIndex() == 5) {
					shaking = true;
					shake_timer = 0;
					motionX *= -1D;
					velocityChanged = true;
					if(!getEntityWorld().isRemote) {
						setHoldStill(true);
						holdCount = 20;
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.WALL_SLAM, SoundCategory.HOSTILE, 0.5F, 0.75F);
					}
				}
				this.impacts += 2;
			}
			else {
				if (state.getBlock() != Blocks.BEDROCK) {
					getEntityWorld().destroyBlock(result.getBlockPos(), false);
					getEntityWorld().notifyNeighborsOfStateChange(result.getBlockPos(), state.getBlock(), true);
				}
			}
		}
	}

private void setHoldStill(boolean hold_still) {
		dataManager.set(HOLD_STILL, hold_still);
	}

public boolean isHoldingStill() {
		return dataManager.get(HOLD_STILL);
	}

@Override
	public AxisAlignedBB getCollisionBoundingBox() {
		return getEntityBoundingBox();
	}

@Override
	public AxisAlignedBB getEntityBoundingBox() {
		if (getHorizontalFacing() == EnumFacing.NORTH || getHorizontalFacing() == EnumFacing.SOUTH)
			return new AxisAlignedBB(posX - 0.5D, posY - 0.5D, posZ - 0.5D, posX + 0.5D, posY + 0.5D, posZ + 0.5D).grow(1D, 1D, 0D).offset(0D, 0.5D, 0D);
		return new AxisAlignedBB(posX - 0.5D, posY - 0.5D, posZ - 0.5D, posX + 0.5D, posY + 0.5D, posZ + 0.5D).grow(0D, 1D, 1D).offset(0D, 0.5D, 0D);
	}

@Override
	protected void readEntityFromNBT(NBTTagCompound nbt) {
		if(nbt.hasKey("new_spawn", Constants.NBT.TAG_BYTE)) {
			setIsNewSpawn(nbt.getBoolean("new_spawn"));
		}

		if(nbt.hasKey("isBlockAligned", Constants.NBT.TAG_BYTE)) {
			this.isBlockAligned = nbt.getBoolean("isBlockAligned");
		}

		if(nbt.hasKey("isDungeonWall", Constants.NBT.TAG_BYTE)) {
			this.isDungeonWall = nbt.getBoolean("isDungeonWall");
		}
	}

@Override
	protected void writeEntityToNBT(NBTTagCompound nbt) {
		nbt.setBoolean("new_spawn", isNewSpawn());
		nbt.setBoolean("isBlockAligned", this.isBlockAligned);
		nbt.setBoolean("isDungeonWall", this.isDungeonWall);
	}

public void tick() {
        super.tick();
        if(this.tickCount % 100 == 0){
            this.heal(2);
        }
        float f = Mth.wrapDegrees(180 + this.getYRot());
        this.yBodyRot = rotlerp(this.yBodyRot, f, 180);
        prevSquidPitch = getSquidPitch();
        prevDepressurization = getDepressurization();
        prevDryProgress = dryProgress;
        prevGrabProgress = grabProgress;
        prevCapturedProgress = capturedProgress;
        if (!this.isInWater() && dryProgress < 5F) {
            dryProgress++;
        }
        if (this.isInWater() && dryProgress > 0F) {
            dryProgress--;
        }

        if (this.isGrabbing()) {
            if (grabProgress < 5F)
                grabProgress += 0.25F;
        } else {
            if (grabProgress > 0F)
                grabProgress -= 0.25F;
        }

        if (this.isCaptured()) {
            if (capturedProgress < 5F)
                capturedProgress += 0.5F;
        } else {
            if (capturedProgress > 0F)
                capturedProgress -= 0.5F;
        }

        if (this.isGrabbing()) {
            Entity target = getGrabbedEntity();
            if(!this.level().isClientSide && target != null){
                this.entityData.set(GRAB_ENTITY, target.getId());
                if (holdTime % 20 == 0 && holdTime > 30) {
                    target.hurt(this.damageSources().mobAttack(this), 3 + random.nextInt(5));
                }
            }
            if (target != null && target.isAlive()) {
                this.setXRot(0);
                float invert = 1F - grabProgress * 0.2F;
                Vec3 extraVec = new Vec3(0, 0, 2F + invert * 7F).xRot(-this.getXRot() * Mth.DEG_TO_RAD).yRot(-this.yBodyRot * Mth.DEG_TO_RAD);
                Vec3 minus = new Vec3(this.getX() + extraVec.x - target.getX(), this.getY() + extraVec.y - target.getY(), this.getZ() + extraVec.z - target.getZ());
                target.setDeltaMovement(minus);
            }
            holdTime++;
            if (holdTime > 1000) {
                holdTime = 0;
                this.setGrabbing(false);
            }
        } else {
            holdTime = 0;
        }
        if (!this.isNoAi()) {
            Vec3[] avector3d = new Vec3[this.allParts.length];
            for (int j = 0; j < this.allParts.length; ++j) {
                this.allParts[j].collideWithNearbyEntities();
                avector3d[j] = new Vec3(this.allParts[j].getX(), this.allParts[j].getY(), this.allParts[j].getZ());
            }
            final float pitch = this.getXRot() * Mth.DEG_TO_RAD * 0.8F;
            this.mantleCollisionPart.setPos(this.getX(), this.getY() - ((this.mantleCollisionPart.getBbHeight() - this.getEyeHeight()) * 0.5F) * (1F - dryProgress * 0.2F), this.getZ());
            this.setPartPositionFromBuffer(this.mantlePart1, pitch, 0.9F, 0);
            this.setPartPositionFromBuffer(this.mantlePart2, pitch, 1.6F, 0);
            this.setPartPositionFromBuffer(this.mantlePart3, pitch, 2.45F, 0);
            this.setPartPositionFromBuffer(this.tentaclesPart1, pitch, -0.8F, 0);
            this.setPartPositionFromBuffer(this.tentaclesPart2, pitch, -1.5F, 0);
            this.setPartPositionFromBuffer(this.tentaclesPart3, pitch, -2.3F, 5);
            this.setPartPositionFromBuffer(this.tentaclesPart4, pitch, -3.4F, 10);
            this.setPartPositionFromBuffer(this.tentaclesPart5, pitch, -5.4F, 15);
            this.setPartPositionFromBuffer(this.tentaclesPart6, pitch, -7.4F, 20);
            if (this.isInWaterOrBubble()) {
                if (this.mantleCollisionPart.scale != 1F) {
                    this.mantleCollisionPart.scale = 1F;
                    this.mantleCollisionPart.refreshDimensions();
                }
            } else {
                if (this.mantleCollisionPart.scale != 0.25F) {
                    this.mantleCollisionPart.scale = 0.25F;
                    this.mantleCollisionPart.refreshDimensions();
                }
            }
            for (int l = 0; l < this.allParts.length; ++l) {
                this.allParts[l].xo = avector3d[l].x;
                this.allParts[l].yo = avector3d[l].y;
                this.allParts[l].zo = avector3d[l].z;
                this.allParts[l].xOld = avector3d[l].x;
                this.allParts[l].yOld = avector3d[l].y;
                this.allParts[l].zOld = avector3d[l].z;
            }
            this.setNoGravity(this.isInWater());
        }
        if (!this.level().isClientSide) {
            if (this.getSquidPitch() > 0F) {
                float decrease = Math.min(2F, this.getSquidPitch());
                this.decrementSquidPitch(decrease);
            }
            if (this.getSquidPitch() < 0F) {
                float decrease = Math.min(2F, -this.getSquidPitch());
                this.incrementSquidPitch(decrease);
            }
            if (this.isInWaterOrBubble()) {
                float dist = (float) this.getDeltaMovement().y() * 45;
                if (entityData.get(OVERRIDE_BODYROT)) {
                    this.decrementSquidPitch(dist);
                } else {
                    this.incrementSquidPitch(dist);
                }
            }
            if (!this.onGround() && this.getFluidHeight(FluidTags.WATER) < this.getBbHeight()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.1F, 0));
            }
            float pressure = getDepressureLevel();
            if (this.getDepressurization() < pressure) {
                this.setDepressurization(this.getDepressurization() + 0.1F);
            }
            if (this.getDepressurization() > pressure) {
                this.setDepressurization(this.getDepressurization() - 0.1F);
            }
        }
        if (this.isHumming()) {
            if (humTick % 20 == 0) {
                this.playSound(AMSoundRegistry.GIANT_SQUID_GAMES.get(), this.getSoundVolume(), 1);
                humTick = 0;
            }
            humTick++;
        }
        if(!this.level().isClientSide){
            if(resetCapturedStateIn > 0){
                resetCapturedStateIn--;
            }else{
                this.setCaptured(false);
            }
        }
    }

@Nullable
    public Entity getGrabbedEntity() {
        if (!this.level().isClientSide || this.entityData.get(GRAB_ENTITY) == -1) {
            return this.getTarget();
        } else {
            return this.level().getEntity(this.entityData.get(GRAB_ENTITY));
        }
    }

